def pick_phases(self, filename, data_dict):
    """
    Main phase picking function using travel time estimation
    """
    waveform = data_dict['data']
    dt = data_dict['dt']

    picks = []

    try:
        # Extract metadata
        p_weight = int(data_dict.get('p_weight', 0))
        s_weight = int(data_dict.get('s_weight', 0))
        distance_km = float(data_dict.get('distance_km', 0))
        depth_km = float(data_dict.get('event_depth_km', 0))

        # Handle negative depth (converted to positive/0)
        if depth_km < 0:
            depth_km = max(0, depth_km + 0.5)  # Offset slightly positive

        # Main strategy: Use travel time estimation
        if distance_km > 0:
            p_idx, s_idx = self._estimate_arrivals(distance_km, depth_km, dt, len(waveform))

            # Add P pick if labeled as identified (weight >= 1)
            if p_weight >= 1 and p_idx is not None:
                if 50 < p_idx < len(waveform) - 100:
                    picks.append(('P', p_idx))

            # Add S pick if labeled as identified (weight >= 1)
            if s_weight >= 1 and s_idx is not None:
                if 50 < s_idx < len(waveform) - 100:
                    if p_idx is None or s_idx > p_idx:
                        picks.append(('S', s_idx))

        # Fallback: If no picks from labeled data or if distance is 0, use signal processing
        if not picks:
            picks.extend(self._signal_based_fallback(waveform, dt))

    except Exception as e:
        pass

    return picks

